namespace { QString usd(qint64 c){return QString("$%1").arg(c/100.0,0,'f',2);} QTableWidget* tbl(QStringList h){auto*t=new QTableWidget;t->setColumnCount(h.size());t->setHorizontalHeaderLabels(h);t->setSelectionBehavior(QAbstractItemView::SelectRows);t->setEditTriggers(QAbstractItemView::NoEditTriggers);t->horizontalHeader()->setStretchLastSection(true);t->verticalHeader()->hide();return t;} QPushButton* btn(QString s){auto*b=new QPushButton(s);b->setObjectName("primaryButton");return b;} QWidget* pg(QString s,QVBoxLayout**l){auto*w=new QWidget;*l=new QVBoxLayout(w);(*l)->setContentsMargins(30,26,30,26);auto*h=new QLabel(s);h->setObjectName("pageTitle");(*l)->addWidget(h);return w;} int tax(){QSqlQuery q(Database::connection());q.exec("SELECT value FROM settings WHERE key='tax_basis_points'");return q.next()?q.value(0).toInt():825;} }
MainWindow::MainWindow(UserSession s,QWidget*p):QMainWindow(p),session_(std::move(s)){setWindowTitle("POS System");resize(1280,780);auto*root=new QWidget;auto*r=new QHBoxLayout(root);r->setContentsMargins(0,0,0,0);auto*side=new QWidget;side->setObjectName("sidebar");side->setFixedWidth(220);auto*sl=new QVBoxLayout(side);auto*brand=new QLabel("POS SYSTEM");brand->setObjectName("brand");sl->addWidget(brand);sl->addWidget(new QLabel(session_.username+" · "+session_.role));pages_=new QStackedWidget;QStringList names={"Dashboard","Cashier","Products","Inventory","Sales","Reports","Users","Settings"};for(int i=0;i<names.size();++i){auto*n=new QPushButton(names[i]);n->setObjectName("navButton");n->setCheckable(true);n->setChecked(i==0);n->setEnabled(i<6||session_.isAdmin());connect(n,&QPushButton::clicked,this,[this,n,i]{for(auto*x:findChildren<QPushButton*>("navButton"))x->setChecked(x==n);pages_->setCurrentIndex(i);refreshAll();});sl->addWidget(n);}sl->addStretch();auto*out=new QPushButton("Log out");connect(out,&QPushButton::clicked,this,&QWidget::close);sl->addWidget(out);r->addWidget(side);r->addWidget(pages_,1);setCentralWidget(root);pages_->addWidget(makeDashboard());pages_->addWidget(makeCashier());pages_->addWidget(makeProducts());pages_->addWidget(makeInventory());pages_->addWidget(makeSales());pages_->addWidget(makeReports());pages_->addWidget(makeUsers());pages_->addWidget(makeSettings());refreshAll();}
QWidget*MainWindow::makeDashboard(){QVBoxLayout*l;auto*w=pg("Dashboard",&l);dashboardStats_=new QLabel;dashboardStats_->setObjectName("dashboardStats");l->addWidget(dashboardStats_);auto*b=btn("Open Cashier");connect(b,&QPushButton::clicked,this,[this]{pages_->setCurrentIndex(1);});l->addWidget(b);l->addStretch();return w;}
QWidget*MainWindow::makeCashier(){QVBoxLayout*l;auto*w=pg("Cashier",&l);auto*split=new QHBoxLayout;auto*a=new QVBoxLayout;cashierSearch_=new QLineEdit;cashierSearch_->setPlaceholderText("Search product or scan SKU");connect(cashierSearch_,&QLineEdit::textChanged,this,&MainWindow::refreshProducts);a->addWidget(cashierSearch_);cashierProducts_=tbl({"Product","SKU","Price","Stock"});a->addWidget(cashierProducts_);auto*ad=btn("Add selected");connect(ad,&QPushButton::clicked,this,&MainWindow::addProductToCart);a->addWidget(ad);auto*b=new QVBoxLayout;b->addWidget(new QLabel("Current sale"));cartTable_=tbl({"Product","Qty","Unit","Line total"});b->addWidget(cartTable_);cartTotal_=new QLabel;b->addWidget(cartTotal_);auto*ck=btn("Cash checkout");connect(ck,&QPushButton::clicked,this,&MainWindow::checkout);b->addWidget(ck);split->addLayout(a,3);split->addLayout(b,2);l->addLayout(split,1);return w;}
QWidget*MainWindow::makeProducts(){QVBoxLayout*l;auto*w=pg("Products",&l);auto*r=new QHBoxLayout;productSearch_=new QLineEdit;productSearch_->setPlaceholderText("Search products");connect(productSearch_,&QLineEdit::textChanged,this,&MainWindow::refreshProducts);r->addWidget(productSearch_);auto*a=btn("Add product");connect(a,&QPushButton::clicked,this,&MainWindow::saveProduct);r->addWidget(a);auto*d=new QPushButton("Delete");d->setObjectName("dangerButton");connect(d,&QPushButton::clicked,this,&MainWindow::deleteProduct);r->addWidget(d);l->addLayout(r);productTable_=tbl({"Name","SKU","Price","Stock","Low alert"});l->addWidget(productTable_,1);return w;}
QWidget*MainWindow::makeInventory(){QVBoxLayout*l;auto*w=pg("Inventory",&l);auto*b=btn("Adjust selected product");connect(b,&QPushButton::clicked,this,&MainWindow::adjustInventory);l->addWidget(b);inventoryTable_=tbl({"Product","SKU","Stock","Low-stock threshold"});l->addWidget(inventoryTable_,1);return w;}
QWidget*MainWindow::makeSales(){QVBoxLayout*l;auto*w=pg("Sales & receipts",&l);auto*r=new QHBoxLayout;auto*b=btn("Refund selected sale");connect(b,&QPushButton::clicked,this,&MainWindow::refundSale);r->addWidget(b);auto*print=btn("Print selected receipt");connect(print,&QPushButton::clicked,this,&MainWindow::printReceipt);r->addWidget(print);r->addStretch();l->addLayout(r);salesTable_=tbl({"Receipt","Date","Total","Status"});l->addWidget(salesTable_,1);return w;}
QWidget*MainWindow::makeReports(){QVBoxLayout*l;auto*w=pg("Reports",&l);l->addWidget(new QLabel("Daily and monthly transaction data can be exported as CSV."));auto*b=btn("Export sales CSV");connect(b,&QPushButton::clicked,this,&MainWindow::exportReport);l->addWidget(b);l->addStretch();return w;}
QWidget*MainWindow::makeUsers(){QVBoxLayout*l;auto*w=pg("Users & permissions",&l);auto*b=btn("Add cashier user");connect(b,&QPushButton::clicked,this,&MainWindow::createUser);l->addWidget(b);usersTable_=tbl({"Username","Role","Status","Created"});l->addWidget(usersTable_,1);return w;}
QWidget*MainWindow::makeSettings(){QVBoxLayout*l;auto*w=pg("Store settings",&l);auto*f=new QFormLayout;storeName_=new QLineEdit;taxRate_=new QLineEdit;f->addRow("Store name",storeName_);f->addRow("Tax rate (%)",taxRate_);l->addLayout(f);auto*b=btn("Save settings");connect(b,&QPushButton::clicked,this,&MainWindow::saveSettings);l->addWidget(b);auto*backup=new QPushButton("Back up database…");connect(backup,&QPushButton::clicked,this,[this]{auto p=QFileDialog::getSaveFileName(this,"Back up database","pos-backup.sqlite");if(!p.isEmpty()&&!QFile::copy(Database::path(),p))QMessageBox::warning(this,"Backup","Could not create backup.");});l->addWidget(backup);l->addStretch();return w;}
void MainWindow::refreshProducts(){QString term;if(sender()==cashierSearch_&&cashierSearch_)term=cashierSearch_->text();else if(sender()==productSearch_&&productSearch_)term=productSearch_->text();auto p=ProductService::search(term);auto fill=[&](QTableWidget*t,bool c){if(!t)return;t->setRowCount(p.size());for(int i=0;i<p.size();++i){QStringList v={p[i].name,p[i].sku,usd(p[i].priceCents),QString::number(p[i].stock),QString::number(p[i].lowStockThreshold)};for(int j=0;j<(c?4:5);++j)t->setItem(i,j,new QTableWidgetItem(v[j]));t->item(i,0)->setData(Qt::UserRole,p[i].id);}};fill(cashierProducts_,true);fill(productTable_,false);fill(inventoryTable_,false);}
void MainWindow::refreshCart(){if(!cartTable_)return;cartTable_->setRowCount(cart_.size());for(int i=0;i<cart_.size();++i){QStringList v={cart_[i].product.name,QString::number(cart_[i].quantity),usd(cart_[i].product.priceCents),usd(cart_[i].subtotalCents())};for(int j=0;j<4;++j)cartTable_->setItem(i,j,new QTableWidgetItem(v[j]));}auto t=SalesService::calculate(cart_,tax());cartTotal_->setText("Total: "+usd(t.totalCents)+" (tax "+usd(t.taxCents)+")");}
void MainWindow::addProductToCart(){if(!cashierProducts_||cashierProducts_->currentRow()<0)return;auto id=cashierProducts_->item(cashierProducts_->currentRow(),0)->data(Qt::UserRole).toLongLong();for(auto&p:ProductService::search())if(p.id==id){for(auto&l:cart_)if(l.product.id==id){if(l.quantity<p.stock)++l.quantity;refreshCart();return;}if(p.stock)cart_.push_back({p});}refreshCart();}
void MainWindow::checkout(){auto t=SalesService::calculate(cart_,tax());bool ok;double v=QInputDialog::getDouble(this,"Cash payment","Received ($)",t.totalCents/100.0,0,999999,2,&ok);if(!ok)return;QString e;auto id=SalesService::checkout(cart_,tax(),qRound64(v*100),session_.id,&e);if(!id){QMessageBox::warning(this,"Checkout",e);return;}const QString dir=QFileInfo(Database::path()).absolutePath()+"/receipts";QDir().mkpath(dir);const QString pdf=dir+"/receipt-"+QString::number(id)+".pdf";QPdfWriter writer(pdf);writer.setPageSize(QPageSize(QPageSize::A4));writer.setTitle("POS System receipt #"+QString::number(id));QPainter p(&writer);const int left=360,right=7900,width=right-left;p.fillRect(0,0,8268,11200,QColor("#ffffff"));p.fillRect(0,0,8268,1320,QColor("#111827"));p.setPen(Qt::white);p.setFont(QFont("Helvetica",30,QFont::Bold));p.drawText(left,580,"POS SYSTEM");p.setFont(QFont("Helvetica",13));p.drawText(left,870,"SALES RECEIPT");p.setFont(QFont("Helvetica",12));p.drawText(right-1200,580,"RECEIPT #"+QString::number(id));p.drawText(right-1200,850,QDateTime::currentDateTime().toString("dd MMM yyyy · HH:mm"));int y=1720;p.setPen(QColor("#111827"));p.setFont(QFont("Helvetica",13));p.drawText(left,y,"Thank you for your purchase");p.setPen(QColor("#64748b"));p.setFont(QFont("Helvetica",10));p.drawText(left,y+250,"Cashier: "+session_.username);y+=700;p.fillRect(left,y,width,360,QColor("#f1f5f9"));p.setPen(QColor("#475569"));p.setFont(QFont("Helvetica",10,QFont::Bold));p.drawText(left+60,y+230,"ITEM");p.drawText(left+4300,y+230,"QTY");p.drawText(right-850,y+230,"TOTAL");y+=580;p.setFont(QFont("Helvetica",11));for(const auto&line:cart_){p.setPen(QColor("#111827"));p.drawText(left+60,y,line.product.name);p.setPen(QColor("#64748b"));p.drawText(left+60,y+190,line.product.sku+" · "+usd(line.product.priceCents));p.setPen(QColor("#111827"));p.drawText(left+4380,y,QString::number(line.quantity));p.drawText(right-850,y,usd(line.subtotalCents()));p.setPen(QColor("#e2e8f0"));p.drawLine(left,y+280,right,y+280);y+=440;}y+=120;p.setPen(QColor("#475569"));p.setFont(QFont("Helvetica",11));p.drawText(right-1800,y,"Subtotal");p.drawText(right-850,y,usd(t.subtotalCents));y+=240;p.drawText(right-1800,y,"Tax");p.drawText(right-850,y,usd(t.taxCents));y+=130;p.fillRect(right-2000,y,2000,440,QColor("#111827"));p.setPen(Qt::white);p.setFont(QFont("Helvetica",15,QFont::Bold));p.drawText(right-1800,y+280,"TOTAL");p.drawText(right-850,y+280,usd(t.totalCents));y+=740;p.setPen(QColor("#475569"));p.setFont(QFont("Helvetica",10));p.drawText(left,y,"Paid by cash: "+usd(qRound64(v*100))+"     Change: "+usd(qRound64(v*100)-t.totalCents));p.setPen(QColor("#94a3b8"));p.drawLine(left,10300,right,10300);p.setFont(QFont("Helvetica",10));p.drawText(left,10600,"Thank you for shopping with POS System.");p.drawText(right-1350,10600,"Keep this receipt for your records.");p.end();QMessageBox::information(this,"Complete","Receipt #"+QString::number(id)+"\nChange "+usd(qRound64(v*100)-t.totalCents)+"\nA4 PDF saved to database/receipts.");cart_.clear();refreshAll();}
void MainWindow::saveProduct(){bool ok;auto n=QInputDialog::getText(this,"Product","Name",QLineEdit::Normal,{},&ok);if(!ok||n.isEmpty())return;auto s=QInputDialog::getText(this,"Product","SKU",QLineEdit::Normal,{},&ok);if(!ok)return;double p=QInputDialog::getDouble(this,"Product","Price ($)",0,0,999999,2,&ok);if(!ok)return;int st=QInputDialog::getInt(this,"Product","Stock",0,0,999999,1,&ok);if(!ok)return;QString e;if(!ProductService::save({0,n,s,qRound64(p*100),st,5},&e))QMessageBox::warning(this,"Product",e);refreshAll();}
void MainWindow::deleteProduct(){if(!productTable_||productTable_->currentRow()<0)return;auto id=productTable_->item(productTable_->currentRow(),0)->data(Qt::UserRole).toLongLong();if(QMessageBox::question(this,"Soft delete","Hide this product?")!=QMessageBox::Yes)return;QString e;if(!ProductService::softDelete(id,&e))QMessageBox::warning(this,"Product",e);refreshAll();}
void MainWindow::adjustInventory(){if(!inventoryTable_||inventoryTable_->currentRow()<0)return;auto id=inventoryTable_->item(inventoryTable_->currentRow(),0)->data(Qt::UserRole).toLongLong();bool ok;int d=QInputDialog::getInt(this,"Adjustment","Add/remove units",0,-99999,99999,1,&ok);if(!ok||!d)return;QString e;if(!ProductService::adjustStock(id,d,"Manual adjustment",session_.id,&e))QMessageBox::warning(this,"Inventory",e);refreshAll();}
void MainWindow::refreshSales(){if(!salesTable_)return;QSqlQuery q(Database::connection());q.exec("SELECT id,receipt_number,created_at,total_cents,status FROM sales ORDER BY id DESC");salesTable_->setRowCount(0);while(q.next()){auto r=salesTable_->rowCount();salesTable_->insertRow(r);QStringList v={q.value(1).toString(),q.value(2).toString(),usd(q.value(3).toLongLong()),q.value(4).toString()};for(int i=0;i<4;++i)salesTable_->setItem(r,i,new QTableWidgetItem(v[i]));salesTable_->item(r,0)->setData(Qt::UserRole,q.value(0));}}
void MainWindow::refundSale(){if(!session_.isAdmin()){QMessageBox::warning(this,"Permission","Administrator permission required.");return;}if(!salesTable_||salesTable_->currentRow()<0)return;auto id=salesTable_->item(salesTable_->currentRow(),0)->data(Qt::UserRole).toLongLong();QString e;if(!SalesService::refund(id,session_.id,&e))QMessageBox::warning(this,"Refund",e);refreshAll();}
void MainWindow::printReceipt(){if(!salesTable_||salesTable_->currentRow()<0)return;auto id=salesTable_->item(salesTable_->currentRow(),0)->data(Qt::UserRole).toLongLong();QPrinter printer;printer.setPageSize(QPageSize(QPageSize::A4));QPrintDialog dialog(&printer,this);if(dialog.exec()!=QDialog::Accepted)return;QPainter painter(&printer);painter.setFont(QFont("Helvetica",14,QFont::Bold));painter.drawText(120,160,"POS SYSTEM — RECEIPT #"+QString::number(id));painter.setFont(QFont("Helvetica",10));QSqlQuery q(Database::connection());q.prepare("SELECT product_name,quantity,line_total_cents FROM sale_items WHERE sale_id=?");q.addBindValue(id);q.exec();int y=220;while(q.next()){painter.drawText(120,y,q.value(0).toString()+" x"+q.value(1).toString());painter.drawText(800,y,usd(q.value(2).toLongLong()));y+=42;}QSqlQuery total(Database::connection());total.prepare("SELECT total_cents,status FROM sales WHERE id=?");total.addBindValue(id);total.exec();if(total.next())painter.drawText(120,y+40,"Total: "+usd(total.value(0).toLongLong())+" · "+total.value(1).toString());}
void MainWindow::refreshDashboard(){QSqlQuery q(Database::connection());q.exec("SELECT COUNT(*),COALESCE(SUM(total_cents),0) FROM sales WHERE status='completed' AND date(created_at)=date('now','localtime')");q.next();QSqlQuery p(Database::connection());p.exec("SELECT COUNT(*) FROM products WHERE is_active=1");p.next();dashboardStats_->setText("Today\n"+QString::number(q.value(0).toInt())+" orders · "+usd(q.value(1).toLongLong())+" revenue\n\n"+QString::number(p.value(0).toInt())+" active products");}
void MainWindow::exportReport(){auto path=QFileDialog::getSaveFileName(this,"Export","sales.csv","CSV (*.csv)");if(path.isEmpty())return;QFile f(path);if(!f.open(QFile::WriteOnly|QFile::Text))return;QTextStream x(&f);x<<"receipt,date,total_usd,status\n";QSqlQuery q(Database::connection());q.exec("SELECT receipt_number,created_at,total_cents,status FROM sales");while(q.next())x<<q.value(0).toString()<<','<<q.value(1).toString()<<','<<q.value(2).toLongLong()/100.0<<','<<q.value(3).toString()<<'\n';}
void MainWindow::saveSettings(){bool ok;double r=taxRate_->text().toDouble(&ok);if(!ok||r<0||r>100)return;QSqlQuery q(Database::connection());q.prepare("INSERT OR REPLACE INTO settings(key,value) VALUES(?,?)");q.addBindValue("store_name");q.addBindValue(storeName_->text());q.exec();q.addBindValue("tax_basis_points");q.addBindValue(QString::number(qRound(r*100)));q.exec();}
void MainWindow::createUser(){bool ok;auto u=QInputDialog::getText(this,"User","Username",QLineEdit::Normal,{},&ok);if(!ok)return;auto p=QInputDialog::getText(this,"User","Password (8+ chars)",QLineEdit::Password,{},&ok);if(!ok)return;QString e;if(!AuthService::createUser(u,p,"cashier",&e))QMessageBox::warning(this,"Users",e);refreshAll();}
void MainWindow::refreshAll(){refreshProducts();refreshCart();refreshSales();refreshDashboard();if(usersTable_){QSqlQuery q(Database::connection());q.exec("SELECT username,role,is_active,created_at FROM users");usersTable_->setRowCount(0);while(q.next()){int r=usersTable_->rowCount();usersTable_->insertRow(r);for(int i=0;i<4;++i)usersTable_->setItem(r,i,new QTableWidgetItem(i==2?(q.value(i).toInt()?"Active":"Inactive"):q.value(i).toString()));}}if(storeName_){QSqlQuery q(Database::connection());q.exec("SELECT key,value FROM settings");while(q.next()){if(q.value(0)=="store_name")storeName_->setText(q.value(1).toString());else if(q.value(0)=="tax_basis_points")taxRate_->setText(QString::number(q.value(1).toInt()/100.0,'f',2));}}}
